// Gibt für jeden PDF-Anhang einen eigenen Eintrag weiter.
// Neuer Dateiname: JJJJ-MM-TT_Absender_Originalname.pdf
const ergebnis = [];

for (const item of $input.all()) {
  const anhaenge = item.binary || {};
  const datum = new Date(item.json.date || Date.now()).toISOString().slice(0, 10);
  const absender = String(item.json.from || 'unbekannt')
    .replace(/<.*>/, '')
    .replace(/"/g, '')
    .trim()
    .replace(/[^A-Za-z0-9ÄÖÜäöüß]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40) || 'unbekannt';

  for (const datei of Object.values(anhaenge)) {
    const istPdf = datei.mimeType === 'application/pdf' || /\.pdf$/i.test(datei.fileName || '');
    if (!istPdf) continue;
    const original = (datei.fileName || 'rechnung.pdf').replace(/[^A-Za-z0-9ÄÖÜäöüß._-]+/g, '-');
    ergebnis.push({
      json: {
        absender: item.json.from,
        betreff: item.json.subject,
        neuerName: `${datum}_${absender}_${original}`,
      },
      binary: { data: datei },
    });
  }
}

// Keine PDF-Anhänge: Der Workflow endet hier ohne Fehler.
return ergebnis;

